#![feature(test)]
extern crate test;
include!("methods.rs");
#[derive(Clone,Copy)]struct Rgb(u8,u8,u8);
#[bench]fn original_swap_with_slice_u8_30(b:&mut test::Bencher){let mapper=|i|i as u8;let mut x=(0usize..30).map(&mapper).collect::<Vec<_>>();let mut y=(30usize..60).map(&mapper).collect::<Vec<_>>();let mut skip=0;b.iter(||{for _ in 0..32{let a=&mut x[skip..];let b=&mut y[..30-skip];a.swap_with_slice(b);skip=black_box(skip+1)%8;}black_box((x[30/3].clone(),y[30*2/3].clone()))});}
